def run(request):
    state=dict(request["state"])
    mode=request["mode"]
    if mode=="time_initialize":
        return {"state":{"advances":0},"effects":[]}
    if mode=="time_advance":
        state["advances"]=state.get("advances",0)+1
        elapsed=request["event"]["minutes"]*request["config"].get("multiplier",1)
        return {"state":state,"effects":[],"elapsed_minutes":elapsed}
    if mode=="view":
        return {"state":state,"effects":[],"view":{"cards":[],"actions":[]}}
    return {"state":state,"effects":[],"context":{}}
